import json,re,hashlib,pymupdf,difflib
from pathlib import Path
base=Path('data/small_track_real_training');p=Path('data/small_track_legacy/official-history-informator-2025.pdf');d=pymupdf.open(p)
def clean(i):return '\n'.join(x for x in d[i].get_text(sort=True).splitlines() if not re.search(r'Informator o egzaminie|Przykładowe zadania z rozwiązaniami',x)).strip()
rows=[json.loads((base/'supplemental-official-essay.jsonl').read_text())]
